// ##################

import type { ColumnDef, Row } from "@tanstack/react-table";
import type { UsersWithoutFoto } from "@tepian-k3/types/platform/users.types";
import { queryClient, trpc } from "@/utils/trpc";
import { Route } from "@/routes/(core)/back-office/users";
import { useMutation, useSuspenseQuery } from "@tanstack/react-query";
import { globalErrorToast, globalSuccessToast } from "@/lib/toast";
import {
  ArchiveRestore,
  CheckCircle,
  Trash,
  Eye,
  Pencil,
  Ellipsis,
  LoaderCircle,
  XCircle,
} from "lucide-react";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import {
  createActionColumn,
  createDateColumn,
  createNumberColumn,
  createTextColumn,
} from "@/lib/column-helpers";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { useNavigate } from "@tanstack/react-router";
import { useState } from "react";

interface UsersColumnsProps {
  currentPage: number;
  perPage: number;
}

function ActionCell({ row }: { row: Row<UsersWithoutFoto> }) {
  const navigate = useNavigate();
  const params = Route.useSearch();
  const queryOptions = trpc.platform.user.getUserPaginated.queryOptions(params);

  const [activeDialog, setActiveDialog] = useState<
    | "none"
    | "delete_options"
    | "restore_confirm"
    | "hard_delete_confirm"
    | "reject_confirm"
  >("none");
  const [rejectionReason, setRejectionReason] = useState("");

  const { data: profile } = useSuspenseQuery(
    trpc.platform.auth.profile.queryOptions(),
  );

  const canSeeDetail = profile.permissions.includes("users.read");
  const canEdit = profile.permissions.includes("users.update");
  const canDelete = profile.permissions.includes("users.delete");

  // Check if current user is super_admin, admin, or admin_pelatihan
  const hasVerificationRole = profile.roles.some((role) =>
    ["super_admin", "admin", "admin_pelatihan"].includes(role.name),
  );

  const verifyUserMutation = useMutation(
    trpc.platform.user.verifyUser.mutationOptions({
      onSuccess: () => {
        globalSuccessToast("User berhasil diverifikasi");
        setActiveDialog("none");
        void queryClient.invalidateQueries(queryOptions);
      },
      onError: (error) => {
        globalErrorToast("Gagal memverifikasi user: " + error.message);
      },
    }),
  );

  const rejectUserMutation = useMutation(
    trpc.platform.user.rejectUser.mutationOptions({
      onSuccess: () => {
        globalSuccessToast("User berhasil ditolak");
        setActiveDialog("none");
        setRejectionReason("");
        void queryClient.invalidateQueries(queryOptions);
      },
      onError: (error) => {
        globalErrorToast("Gagal menolak user: " + error.message);
      },
    }),
  );

  const deleteMutation = useMutation(
    trpc.platform.user.deleteUser.mutationOptions({
      onSuccess: () => {
        globalSuccessToast("Berhasil menghapus sementara user");
        setActiveDialog("none");
        void queryClient.invalidateQueries(queryOptions);
      },
      onError: (error) => {
        globalErrorToast("Gagal menghapus user: " + error.message);
      },
    }),
  );

  const restoreMutation = useMutation(
    trpc.platform.user.restoreUser.mutationOptions({
      onSuccess: () => {
        globalSuccessToast("Berhasil mengembalikan user");
        setActiveDialog("none");
        void queryClient.invalidateQueries(queryOptions);
      },
      onError: (error) => {
        globalErrorToast("Gagal mengembalikan user: " + error.message);
      },
    }),
  );

  const hardDeleteMutation = useMutation(
    trpc.platform.user.hardDeleteUser.mutationOptions({
      onSuccess: () => {
        globalSuccessToast("Berhasil menghapus permanen user");
        setActiveDialog("none");
        void queryClient.invalidateQueries(queryOptions);
      },
      onError: (error) => {
        globalErrorToast("Gagal menghapus permanen user: " + error.message);
      },
    }),
  );

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger aria-label="Buka menu aksi" asChild>
          <Button variant="ghost" size="icon" className="size-8 p-0">
            <Ellipsis className="size-4" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-48">
          {/* Detail Action */}
          {canSeeDetail && (
            <DropdownMenuItem
              onClick={() =>
                navigate({ to: `/back-office/users/${row.original.id}/edit` })
              }
            >
              <Eye className="mr-2 size-4" />
              Lihat Detail
            </DropdownMenuItem>
          )}

          {/* Edit Action */}
          {canEdit && !row.original.deletedAt && (
            <DropdownMenuItem
              onClick={() =>
                navigate({ to: `/back-office/users/${row.original.id}/edit` })
              }
            >
              <Pencil className="mr-2 size-4" />
              Edit
            </DropdownMenuItem>
          )}

          {/* Terima Verifikasi Action */}
          {hasVerificationRole &&
            row.original.verificationStatus !== "approved" &&
            !row.original.deletedAt && (
              <DropdownMenuItem
                onClick={() =>
                  verifyUserMutation.mutate({ userId: row.original.id })
                }
              >
                <CheckCircle className="mr-2 size-4 text-green-600" />
                Terima Verifikasi
              </DropdownMenuItem>
            )}

          {/* Tolak Verifikasi Action */}
          {hasVerificationRole &&
            row.original.verificationStatus === "pending" &&
            !row.original.deletedAt && (
              <DropdownMenuItem
                onClick={() => {
                  setRejectionReason("");
                  setActiveDialog("reject_confirm");
                }}
              >
                <XCircle className="mr-2 size-4 text-red-600" />
                Tolak Verifikasi
              </DropdownMenuItem>
            )}

          {/* Restore / Hapus Action */}
          {row.original.deletedAt ? (
            <>
              {canDelete && (
                <DropdownMenuItem
                  onClick={() => setActiveDialog("restore_confirm")}
                >
                  <ArchiveRestore className="mr-2 size-4 text-blue-600" />
                  Kembalikan
                </DropdownMenuItem>
              )}
              {canDelete && (
                <DropdownMenuItem
                  className="text-red-600 focus:bg-red-50 focus:text-red-600"
                  onClick={() => setActiveDialog("hard_delete_confirm")}
                >
                  <Trash className="mr-2 size-4" />
                  Hapus Permanen
                </DropdownMenuItem>
              )}
            </>
          ) : (
            canDelete && (
              <DropdownMenuItem
                className="text-red-600 focus:bg-red-50 focus:text-red-600"
                onClick={() => setActiveDialog("delete_options")}
              >
                <Trash className="mr-2 size-4" />
                Hapus
              </DropdownMenuItem>
            )
          )}
        </DropdownMenuContent>
      </DropdownMenu>

      <AlertDialog
        open={activeDialog !== "none"}
        onOpenChange={(open) => {
          if (!open) setActiveDialog("none");
        }}
      >
        <AlertDialogContent>
          {activeDialog === "delete_options" && (
            <>
              <AlertDialogHeader>
                <AlertDialogTitle>Hapus User</AlertDialogTitle>
                <AlertDialogDescription>
                  Pilih metode penghapusan untuk pengguna{" "}
                  <strong>{row.original.name}</strong>. Anda dapat menonaktifkan
                  pengguna sementara (soft delete), atau menghapusnya secara
                  permanen dari database.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter className="flex flex-col gap-2 sm:flex-row">
                <AlertDialogCancel>Batal</AlertDialogCancel>
                <Button
                  variant="outline"
                  onClick={() => deleteMutation.mutate({ id: row.original.id })}
                  disabled={
                    deleteMutation.isPending || hardDeleteMutation.isPending
                  }
                >
                  {deleteMutation.isPending && (
                    <LoaderCircle className="mr-2 h-4 w-4 animate-spin" />
                  )}
                  Hapus Sementara
                </Button>
                <Button
                  variant="destructive"
                  onClick={() =>
                    hardDeleteMutation.mutate({ id: row.original.id })
                  }
                  disabled={
                    deleteMutation.isPending || hardDeleteMutation.isPending
                  }
                >
                  {hardDeleteMutation.isPending && (
                    <LoaderCircle className="mr-2 h-4 w-4 animate-spin" />
                  )}
                  Hapus Permanen
                </Button>
              </AlertDialogFooter>
            </>
          )}

          {activeDialog === "restore_confirm" && (
            <>
              <AlertDialogHeader>
                <AlertDialogTitle>Kembalikan data user</AlertDialogTitle>
                <AlertDialogDescription>
                  Apakah anda yakin ingin mengembalikan data user{" "}
                  <strong>{row.original.name}</strong>?
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Batal</AlertDialogCancel>
                <AlertDialogAction
                  onClick={() =>
                    restoreMutation.mutate({ id: row.original.id })
                  }
                  disabled={restoreMutation.isPending}
                >
                  {restoreMutation.isPending && (
                    <LoaderCircle className="mr-2 h-4 w-4 animate-spin" />
                  )}
                  Kembalikan
                </AlertDialogAction>
              </AlertDialogFooter>
            </>
          )}

          {activeDialog === "hard_delete_confirm" && (
            <>
              <AlertDialogHeader>
                <AlertDialogTitle>Hapus Permanen data user</AlertDialogTitle>
                <AlertDialogDescription>
                  Apakah anda yakin ingin menghapus data user{" "}
                  <strong>{row.original.name}</strong> secara permanen? Data
                  yang sudah dihapus secara permanen tidak dapat dikembalikan.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Batal</AlertDialogCancel>
                <AlertDialogAction
                  className="bg-red-600 text-white hover:bg-red-500"
                  onClick={() =>
                    hardDeleteMutation.mutate({ id: row.original.id })
                  }
                  disabled={hardDeleteMutation.isPending}
                >
                  {hardDeleteMutation.isPending && (
                    <LoaderCircle className="mr-2 h-4 w-4 animate-spin" />
                  )}
                  Hapus Permanen
                </AlertDialogAction>
              </AlertDialogFooter>
            </>
          )}

          {activeDialog === "reject_confirm" && (
            <>
              <AlertDialogHeader>
                <AlertDialogTitle>Tolak Verifikasi User</AlertDialogTitle>
                <AlertDialogDescription>
                  Masukkan alasan penolakan verifikasi untuk pengguna{" "}
                  <strong>{row.original.name}</strong>. Alasan ini akan
                  dikirimkan kepada pengguna.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <div className="my-4">
                <Textarea
                  placeholder="Contoh: Nomor telepon tidak valid atau berkas tidak lengkap."
                  value={rejectionReason}
                  onChange={(e) => setRejectionReason(e.target.value)}
                  className="w-full"
                />
              </div>
              <AlertDialogFooter>
                <AlertDialogCancel onClick={() => setRejectionReason("")}>
                  Batal
                </AlertDialogCancel>
                <Button
                  variant="destructive"
                  onClick={() =>
                    rejectUserMutation.mutate({
                      userId: row.original.id,
                      reason: rejectionReason,
                    })
                  }
                  disabled={
                    !rejectionReason.trim() || rejectUserMutation.isPending
                  }
                >
                  {rejectUserMutation.isPending && (
                    <LoaderCircle className="mr-2 h-4 w-4 animate-spin" />
                  )}
                  Tolak Verifikasi
                </Button>
              </AlertDialogFooter>
            </>
          )}
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

export default function getUsersColumns({
  currentPage,
  perPage,
}: UsersColumnsProps): ColumnDef<UsersWithoutFoto>[] {
  return [
    createNumberColumn<UsersWithoutFoto>(currentPage, perPage),
    createTextColumn<UsersWithoutFoto>("name", "Nama User", {
      width: "w-48",
      enableFilter: true,
      placeholder: "Cari nama user...",
    }),
    createTextColumn<UsersWithoutFoto>("email", "Email", {
      width: "w-64",
    }),
    createTextColumn<UsersWithoutFoto>("verificationStatus", "Verifikasi", {
      width: "w-36",
      cellRenderer: (value, row) => {
        const status = value as string;
        const reason = row.original.verificationRejectionReason;

        return (
          <div className="w-36">
            {status === "approved" && (
              <Badge
                variant="secondary"
                className="border-none bg-green-100 text-green-800 hover:bg-green-100"
              >
                Terverifikasi
              </Badge>
            )}
            {status === "pending" && (
              <Badge
                variant="secondary"
                className="border-none bg-yellow-100 text-yellow-800 hover:bg-yellow-100"
              >
                Menunggu Verifikasi
              </Badge>
            )}
            {status === "rejected" && (
              <div
                title={`Alasan penolakan: ${reason ?? "Tidak ada alasan spesifik"}`}
              >
                <Badge
                  variant="secondary"
                  className="cursor-help border-none bg-red-100 text-red-800 hover:bg-red-100"
                >
                  Ditolak
                </Badge>
              </div>
            )}
          </div>
        );
      },
    }),
    createDateColumn<UsersWithoutFoto>("createdAt", "Dibuat"),
    createDateColumn<UsersWithoutFoto>("updatedAt", "Diubah", {
      nullable: true,
    }),
    createActionColumn<UsersWithoutFoto>(({ row }) => <ActionCell row={row} />),
  ];
}

